import React from 'react';
import './About.css';

function About() {
  const highlights = [
    {
      id: 1,
      title: '🎓 Academic Excellence',
      description: 'A platform for showcasing intellectual prowess and academic achievements'
    },
    {
      id: 2,
      title: '🤝 Networking',
      description: 'Connect with like-minded individuals and industry professionals'
    },
    {
      id: 3,
      title: '💡 Innovation',
      description: 'Explore new ideas and creative solutions in various fields'
    }
  ];

  const details = [
    {
      id: 1,
      title: 'Key Dates',
      items: [
        { label: 'Registration Open', value: 'October 1, 2023' },
        { label: 'Submission Deadline', value: 'November 15, 2023' },
        { label: 'Event Day', value: 'December 10, 2023' }
      ]
    },
    {
      id: 2,
      title: 'Location',
      items: [
        { value: 'Crescent Girls\' School Auditorium' },
        { value: '123 Crescent Road, Singapore' }
      ]
    },
    {
      id: 3,
      title: 'Contact',
      items: [
        { label: 'Email', value: 'info@crescentacademia.com' },
        { label: 'Phone', value: '+65 1234 5678' }
      ]
    }
  ];

  return (
    <section id="about" className="about">
      <div className="container">
        <h2 className="animate-down">About the Event</h2>
        <p className="animate-up delay-1">Crescent Academia Moot 2.0 is a prestigious academic event organized by Crescent Girls, bringing together students and professionals for an enriching experience focused on intellectual discourse, debate, and networking.</p>
        <section id="details" className="details">
          <div className="container">
            <h2 className="animate-down">Event Details</h2>
            <div className="details-grid">
              {details.map((detail, index) => (
                <div key={detail.id} className={`detail-item animate-left delay-${index + 1}`}>
                  <h3>{detail.title}</h3>
                  {detail.items.map((item, idx) => (
                    <p key={idx}>
                      {item.label && <strong>{item.label}</strong>}
                      {item.label && ' '}
                      {item.value}
                    </p>
                  ))}
                </div>
              ))}
            </div>
          </div>
        </section>
        <div className="highlights">
          {highlights.map((highlight, index) => (
            <div key={highlight.id} className={`highlight-card animate-zoom delay-${index + 1}`}>
              <h3>{highlight.title}</h3>
              <p>{highlight.description}</p>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

export default About;
